"""Generate the YAML test cases of the pre-registered evaluation matrix.

The script writes one configuration per matrix cell (substrate x adsorbate x
tier) under ``pipeline/configs/``, the pre-registered site lists under
``pipeline/sites/``, and the S6 disordered structure under
``pipeline/structures/``. It does not run any campaign.
"""

from __future__ import annotations

import argparse
import shutil
from pathlib import Path

import yaml

from adsorption.runner.config import AdsorbateConfig, CampaignConfig

from . import matrix

HEADER = (
    "# Generated by pipeline/generate.py. Do not edit by hand.\n"
    "# Tier: {tier}\n"
    "# Protocol values follow paper-1 Section 2 / Appendix B; the screen\n"
    "# thresholds and the MLP model path are placeholders "
    "(see pipeline/README.md).\n"
)


def _write_config(path: Path, config: dict, tier: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    body = yaml.safe_dump(config, sort_keys=False, allow_unicode=True)
    path.write_text(HEADER.format(tier=tier) + body, encoding="utf-8")


def generate(*, clean: bool = False) -> dict[str, int]:
    """Generate the configurations and the site registry.

    Args:
        clean: Whether to remove the existing ``pipeline/configs`` tree first.

    Returns:
        dict[str, int]: Counts of generated files.
    """
    if clean and matrix.CONFIGS_DIR.exists():
        shutil.rmtree(matrix.CONFIGS_DIR)
    matrix.STRUCTURES_DIR.mkdir(parents=True, exist_ok=True)
    matrix.SITES_DIR.mkdir(parents=True, exist_ok=True)
    matrix.REPORTS_DIR.mkdir(parents=True, exist_ok=True)
    if not matrix.DISORDERED_PATH.exists():
        matrix.build_disordered_cluster()

    adsorbate_cache: dict[str, object] = {}
    configs = 0
    empty_sites: list[str] = []
    for key, system in matrix.SYSTEMS.items():
        atoms = matrix.build_substrate(key)
        sites = matrix.choose_sites(key, atoms)
        matrix.dump_sites(matrix.SITES_DIR / f"{system.slug}.json", key, atoms)
        metrics = matrix.site_metrics(key, sites)
        for record in metrics:
            if record["n_oa"] == 0:
                empty_sites.append(f"{key}:{record['label']}")
        for adsorbate in system.adsorbates:
            if adsorbate not in adsorbate_cache:
                spec = AdsorbateConfig.model_validate(
                    matrix.ADSORBATES[adsorbate]
                ).to_spec()
                adsorbate_cache[adsorbate] = spec
            for tier in matrix.tiers_for(key, adsorbate):
                config = matrix.config_for(key, adsorbate, tier, sites)
                CampaignConfig.model_validate(config)
                path = (
                    matrix.CONFIGS_DIR
                    / system.slug
                    / adsorbate
                    / f"{tier}.yaml"
                )
                _write_config(path, config, tier)
                configs += 1
    if empty_sites:
        print(
            "warning: sites without admissible directions: "
            + ", ".join(empty_sites)
        )
    print(
        f"systems: {len(matrix.SYSTEMS)} | adsorbates: "
        f"{len(matrix.ADSORBATES)} | configs: {configs}"
    )
    return {
        "systems": len(matrix.SYSTEMS),
        "adsorbates": len(matrix.ADSORBATES),
        "configs": configs,
    }


def main(argv: list[str] | None = None) -> int:
    """Run the generator.

    Args:
        argv: Command-line arguments.

    Returns:
        int: Process exit code.
    """
    parser = argparse.ArgumentParser(
        description="Generate the pipeline test cases (no campaign is run)."
    )
    parser.add_argument(
        "--clean",
        action="store_true",
        help="remove the existing configs tree first",
    )
    arguments = parser.parse_args(argv)
    generate(clean=arguments.clean)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
